/*
 * Zephyr ADC example with hardware oversampling.
 *
 * This program:
 *   - Retrieves the ADC device from the DT alias "adc0".
 *   - Configures channel 0 with gain 1, internal reference and default acquisition time.
 *   - Sets up an ADC sequence that performs hardware oversampling (2^4 = 16 samples)
 *     and uses a 12‑bit resolution.
 *   - Continuously reads the channel, prints the raw sample value and sleeps 1 s.
 *
 * Target board: nrf52840dk/nrf52840
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

#define ADC_RESOLUTION    12        /* Desired resolution in bits */
#define ADC_OVERSAMPLING  4         /* 2^4 = 16 hardware samples per read */
#define SAMPLE_BUFFER_SIZE 1

/* Static buffer for the ADC sample */
static int16_t sample_buffer[SAMPLE_BUFFER_SIZE];

void main(void)
{
    const struct device *adc_dev;

    /* 1. Get the ADC device from DT alias "adc0" */
    adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));
    if (!device_is_ready(adc_dev)) {
        printk("ADC device not ready\n");
        return;
    }

    /* 2. Define and configure the ADC channel */
    struct adc_channel_cfg channel_cfg = {
        .gain = ADC_GAIN_1,
        .reference = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id = 0,
        .input_positive = 0,   /* For nRF SAADC this maps to AIN0 (default) */
    };

    if (adc_channel_setup(adc_dev, &channel_cfg) != 0) {
        printk("Failed to configure ADC channel\n");
        return;
    }

    /* 4. Define the ADC sequence with hardware oversampling */
    struct adc_sequence sequence = {
        .channels = BIT(0),                     /* Channel 0 */
        .buffer = sample_buffer,
        .buffer_size = sizeof(sample_buffer),
        .resolution = ADC_RESOLUTION,
        .oversampling = ADC_OVERSAMPLING,
        .calibrate = false,
    };

    /* 5‑7. Read loop: acquire, print, sleep */
    while (1) {
        int ret = adc_read(adc_dev, &sequence);
        if (ret == 0) {
            printk("Raw ADC sample: %d\n", sample_buffer[0]);
        } else {
            printk("ADC read error: %d\n", ret);
        }
        k_sleep(K_SECONDS(1));
    }
}
